// pubspec.yaml:
//   flutter_local_notifications: ^17.0.0
//   timezone: ^0.9.0
import 'package:flutter_local_notifications/flutter_local_notifications.dart';
import 'package:timezone/data/latest.dart' as tz_data;
import 'package:timezone/timezone.dart' as tz;
import 'package:flutter_timezone/flutter_timezone.dart';

final notifs = FlutterLocalNotificationsPlugin();

Future<void> initNotifs() async {
  tz_data.initializeTimeZones();
  tz.setLocalLocation(tz.getLocation(await FlutterTimezone.getLocalTimezone()));

  const androidInit = AndroidInitializationSettings('@mipmap/ic_launcher');
  const iosInit = DarwinInitializationSettings(
    requestAlertPermission: false,
    requestBadgePermission: false,
    requestSoundPermission: false,
    notificationCategories: [
      DarwinNotificationCategory('MSG',
        actions: [DarwinNotificationAction.plain('REPLY', 'Reply', options: {DarwinNotificationActionOption.foreground})]),
    ],
  );

  await notifs.initialize(
    const InitializationSettings(android: androidInit, iOS: iosInit),
    onDidReceiveNotificationResponse: _onTap,   // FOREGROUND / BACKGROUND if isolate has state
    onDidReceiveBackgroundNotificationResponse: _bgTap,   // TERMINATED — top-level static
  );

  // Android 8+ channels — create at app start
  await notifs.resolvePlatformSpecificImplementation<AndroidFlutterLocalNotificationsPlugin>()
      ?.createNotificationChannel(const AndroidNotificationChannel(
        'orders', 'Order updates',
        importance: Importance.high, playSound: true));

  // Android 13+ POST_NOTIFICATIONS runtime permission
  await notifs.resolvePlatformSpecificImplementation<AndroidFlutterLocalNotificationsPlugin>()
      ?.requestNotificationsPermission();

  // iOS runtime
  await notifs.resolvePlatformSpecificImplementation<IOSFlutterLocalNotificationsPlugin>()
      ?.requestPermissions(alert: true, badge: true, sound: true);
}

void _onTap(NotificationResponse resp) {
  // parse resp.payload → deep-link
  // e.g., router.go('/orders/${resp.payload}')
}

@pragma('vm:entry-point')
void _bgTap(NotificationResponse resp) {
  // Runs in a background isolate — persist a pending-nav via shared_preferences
}

// ────── Show immediate ──────
await notifs.show(
  1, 'Order shipped', 'Your order #123 is on the way',
  const NotificationDetails(
    android: AndroidNotificationDetails('orders', 'Order updates',
      importance: Importance.high, priority: Priority.high),
    iOS: DarwinNotificationDetails(interruptionLevel: InterruptionLevel.active),
  ),
  payload: '123',
);

// ────── Zoned schedule ──────
final now = tz.TZDateTime.now(tz.local);
await notifs.zonedSchedule(
  2, 'Time to hydrate', 'Take a sip', now.add(const Duration(hours: 1)),
  const NotificationDetails(android: AndroidNotificationDetails('reminders', 'Reminders')),
  uiLocalNotificationDateInterpretation: UILocalNotificationDateInterpretation.absoluteTime,
  androidScheduleMode: AndroidScheduleMode.exactAllowWhileIdle,
  matchDateTimeComponents: DateTimeComponents.time,   // repeat daily
);

// ────── FCM foreground display ──────
FirebaseMessaging.onMessage.listen((msg) async {
  final n = msg.notification;
  if (n == null) return;
  await notifs.show(
    msg.hashCode, n.title, n.body,
    const NotificationDetails(
      android: AndroidNotificationDetails('promos', 'Promotions'),
      iOS: DarwinNotificationDetails(),
    ),
    payload: msg.data['deep_link'],
  );
});
